import test from "node:test";
import assert from "node:assert";
import { hashPassword, verifyPassword } from "../src/lib/auth/password";
import { argon2Verify } from "hash-wasm";

test("Argon2id compatibility with production and native argon2 hashes", async (t) => {
  // Known hash generated by native argon2 (C++ binary) for password "TestPass123!"
  const knownNativeHash = "$argon2id$v=19$m=65536,t=3,p=4$xNo8CIQiwhPU75jrSE5ssw$zxRCKE4xX2dUPLN5VBySZD061vYClEHjBmNMkiSYvNY";
  const password = "TestPass123!";

  await t.test("verifyPassword validates known native argon2 hash", async () => {
    const isValid = await verifyPassword(password, knownNativeHash);
    assert.strictEqual(isValid, true, "Must verify native argon2 hash without errors");
  });

  await t.test("verifyPassword rejects wrong password for known native argon2 hash", async () => {
    const isValid = await verifyPassword("WrongPassword123!", knownNativeHash);
    assert.strictEqual(isValid, false, "Must reject incorrect password");
  });

  await t.test("hashPassword generates valid Argon2id PHC format", async () => {
    const newHash = await hashPassword("NewSecurePassword2026!");
    assert.ok(newHash.startsWith("$argon2id$v=19$m=65536,t=3,p=4$"), `Must match PHC header: ${newHash}`);

    const isValid = await verifyPassword("NewSecurePassword2026!", newHash);
    assert.strictEqual(isValid, true, "Must verify newly generated hash");
  });
});
